+    // ════════════════════════════════════════════════════════════════════
+    // 施术者侧的强度倍率
+    // ════════════════════════════════════════════════════════════════════
+
+    /**
+     * 「三蝶手稿」插件带来的封印强度倍率。
+     *
+     * 判定口径：**手部战技名 == 天启大封印** ⟺ 手套上装了三蝶手稿。
+     * （三蝶手稿的 `<use>` 是 `刀,手部装备,长枪`，装到手套上时
+     *  `EquipmentCalculator.calculateInPlace` 会把 `modifiers.skill` 覆盖进
+     *  `itemData.skill`，`DressupInitializer.loadWeaponSkill` 再拿
+     *  `target["手部装备数据"].skill` 去 `装载主动战技(…, "空手")`。）
+     *
+     * 这样判还顺带解决歧义：手稿装在刀 / 长枪上、手套另配时，手部战技不是
+     * 天启大封印 → 不加成，符合"只有戴着手稿的那只手套才强化封印"的直觉。
+     *
+     *   手部装备 = 真猫妖手套 → 5.0
+     *   手部装备 = 猫妖手套   → 2.0
+     *   其余 / 取不到     → 1.0
+     *
+     * ⚠ 倍率挂在 状态 上（落成时快照一次），**不要**去改静态的 每秒强度 ——
+     *   那是全局量，动了会让所有封印一起变。
+     */
+    private static function 取强度倍率(施术者:MovieClip):Number {
+        if (施术者 == undefined) {
+            return 1;
+        }
+        var 手部数据:Object = 施术者["手部装备数据"];
+        if (手部数据 == undefined || 手部数据 == null || 手部数据.skill == undefined) {
+            return 1;
+        }
+        if (String(手部数据.skill.skillname) != "天启大封印") {
+            return 1;
+        }
+        var 装备名:String = String(手部数据.name == undefined ? "" : 手部数据.name);
+        if (装备名 == "真猫妖手套") {
+            return 5;
+        }
+        if (装备名 == "猫妖手套") {
+            return 2;
+        }
+        return 1;
+    }
+
